#include <map>
#include <string>

void change_key(std::map<std::string, float>& coll,
                  const std::string& old_key,
                  const std::string& new_key) {
    // Check if old key exists and new key doesn't (optional safety)
    if (coll.count(old_key) > 0) {
        // 1. Insert new element (copies value)
        coll[new_key] = coll[old_key]; // O(log N)
        // 2. Remove old element
        coll.erase(old_key);           // O(log N)
    }
}
